import click
from click.testing import CliRunner

def mk(envvar_on_upper, envvar_on_lower):
    @click.command()
    @click.option('--upper', 'transformation', flag_value='upper', envvar='TRANS' if envvar_on_upper else None)
    @click.option('--lower', 'transformation', flag_value='lower', envvar='TRANS' if envvar_on_lower else None)
    @click.pass_context
    def cli(ctx, transformation):
        click.echo(f'{transformation!r} src={ctx.get_parameter_source(\"transformation\").name}')
    return cli

